using System.ComponentModel.DataAnnotations;

namespace Travel.Domain.Enums
{
    public enum AttachmentCategory
    {
        [Display(Name = "Flight")]
        Flight = 1,

        [Display(Name = "Passport")]
        Passport = 2,

        // 3 was DomesticFlight. Those documents belong to the arrival group, not the booking — see
        // BlockAttachment — and the rows were deleted by the migration that moved them. Do not reuse 3.

        [Display(Name = "Contract")]
        Contract = 4,

        /// <summary>
        /// The client contract PDF generated by <c>BookingContractController</c> — at most one per booking,
        /// replaced only by regenerating. Not the <see cref="Contract"/> link row, which an ordinary Edit
        /// deletes when its box is cleared.
        /// </summary>
        [Display(Name = "Generated contract")]
        GeneratedContract = 5,
    }
}
